package com.witchersbestiary.client.sorcery;
import com.witchersbestiary.sorcery.*;import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.option.KeyBinding;import net.minecraft.client.util.InputUtil;import net.minecraft.client.render.*;import net.minecraft.text.Text;import net.fabricmc.fabric.api.client.networking.v1.*;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.rendering.v1.*;import java.util.*;
public final class SorceryClient {
 public static SorceryPackets.View view;private static long sequence;private static KeyBinding cast;
 private record Ice(int id,long end,int duration){}private static final Map<Integer,Ice> ICE=new HashMap<>();
 public static void send(int action){var c=MinecraftClient.getInstance();if(view!=null&&c.world!=null)ClientPlayNetworking.send(new SorceryPackets.Intent(view.session(),++sequence,action));}
 public static void initialize(){cast=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.sorcery",InputUtil.Type.KEYSYM,org.lwjgl.glfw.GLFW.GLFW_KEY_UNKNOWN,"key.categories.gameplay"));ClientPlayNetworking.registerGlobalReceiver(SorceryPackets.View.ID,(p,c)->c.client().execute(()->view=p));ClientPlayNetworking.registerGlobalReceiver(SorceryPackets.Effect.ID,(p,c)->c.client().execute(()->{if(c.client().world!=null){if(ICE.size()>=64)ICE.clear();ICE.put(p.entity(),new Ice(p.entity(),c.client().world.getTime()+Math.clamp(p.ticks(),1,60),Math.clamp(p.ticks(),1,60)));}}));ClientPlayConnectionEvents.DISCONNECT.register((h,c)->{view=null;sequence=0;ICE.clear();});net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientWorldEvents.AFTER_CLIENT_WORLD_CHANGE.register((c,w)->ICE.clear());ClientTickEvents.END_CLIENT_TICK.register(c->{while(cast.wasPressed())if(c.player!=null&&c.currentScreen==null&&c.isWindowFocused())send(1);});
  HudRenderCallback.EVENT.register((draw,tick)->{var c=MinecraftClient.getInstance();if(c.player==null||view==null||!view.learned()||c.currentScreen!=null||c.options.hudHidden||com.witchersbestiary.client.fist.FistClient.status()!=null)return;int y=c.getWindow().getScaledHeight()-69;draw.fill(6,y-3,190,y+24,0xa0182639);draw.drawTextWithShadow(c.textRenderer,Text.translatable("spell.witchersbestiary.icy_grasp"),12,y,0xff90dfff);draw.drawTextWithShadow(c.textRenderer,Text.translatable("sorcery.witchersbestiary.cost"),12,y+12,0xffbdd3e5);draw.drawTextWithShadow(c.textRenderer,String.format(java.util.Locale.ROOT,"%.1fs",view.cooldown()/20f),157,y+12,0xffeeeeff);});
  WorldRenderEvents.AFTER_ENTITIES.register(context->{var c=MinecraftClient.getInstance();if(c.world==null)return;ICE.values().removeIf(ice->ice.end()<c.world.getTime()||c.world.getEntityById(ice.id())==null);var matrices=context.matrixStack();var camera=context.camera().getPos();for(var ice:ICE.values()){var e=c.world.getEntityById(ice.id());if(e==null||!e.isAlive()||e.squaredDistanceTo(camera)>48*48)continue;double remaining=ice.end()-c.world.getTime();float growth=(float)Math.min(1,Math.min((ice.duration()-remaining)/5.0,remaining/8.0));if(growth<=0)continue;matrices.push();matrices.translate(e.getX()-camera.x,e.getY()-camera.y,e.getZ()-camera.z);var vertices=context.consumers().getBuffer(RenderLayer.getDebugQuads());var matrix=matrices.peek().getPositionMatrix();double radius=Math.min(1.8,e.getWidth()*.5+.28);for(int i=0;i<6;i++){double angle=i*Math.PI/3;float x=(float)(Math.cos(angle)*radius),z=(float)(Math.sin(angle)*radius),height=(.65f+(i%3)*.22f)*growth;float[][] points={{x-.15f,0,z-.15f},{x+.15f,0,z-.15f},{x+.15f,0,z+.15f},{x-.15f,0,z+.15f}};for(int face=0;face<4;face++){var a=points[face];var b=points[(face+1)%4];vertices.vertex(matrix,a[0],0,a[2]).color(48,142,209,180);vertices.vertex(matrix,b[0],0,b[2]).color(75,186,238,180);vertices.vertex(matrix,x,height,z).color(185,242,255,210);vertices.vertex(matrix,x,height,z).color(185,242,255,210);}}matrices.pop();}});
 }
}
